contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        c.sendMoney(address(c), amount); if (__ESBMC_reverted()) return;

        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterSelf = address(this).balance;

        assert(
            (value <= beforeC && !reverted && afterC == beforeC - value && afterSelf == beforeSelf + value)
            ||
            (value > beforeC && reverted && afterC == beforeC && afterSelf == beforeSelf)
        );
    }

    receive() external payable {}
}

