// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount, uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.sendMoney(address(c), amount) {} catch { return; }
        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;
        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterC = address(c).balance;
        uint afterSelf = address(this).balance;
        assertTrue((value <= beforeC && !reverted && afterC == beforeC - value && afterSelf == beforeSelf + value)
            ||
            (value > beforeC && reverted && afterC == beforeC && afterSelf == beforeSelf));
    }

    function testFuzz_run(uint256 amount, uint256 value) public {
        _run(amount, value);
    }

    receive() external payable {}
}
